"""Reviewer-01 independent custody check: outer manifest, exact 13-file set, inner manifest, 47 external pins.
Run: TMPDIR=<scratch> PY -I -B verify_subject.py LABEL OUT.json"""
import hashlib
import json
import os
import sys
from pathlib import Path

ROOT = Path("/tmp/opensip-implementation")
SUBJ = ROOT / "m1-report-evidence-design-subject-01"
OUTER = ROOT / "m1-report-evidence-design-subject-01.json"
OUTER_SHA = "0af84231305e54ec218a5efeff4f0489b02f9dc69ade0c6101c632c96ffaaa11"


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def main():
    label, out = sys.argv[1], sys.argv[2]
    errors = []
    outer_raw = OUTER.read_bytes()
    if hashlib.sha256(outer_raw).hexdigest() != OUTER_SHA:
        errors.append("outer-manifest-sha")
    outer = json.loads(outer_raw)
    actual = sorted(str(p.relative_to(SUBJ)) for p in SUBJ.rglob("*") if p.is_file() or p.is_symlink())
    dirs = sorted(str(p.relative_to(SUBJ)) for p in SUBJ.rglob("*") if p.is_dir())
    if len(actual) != 13:
        errors.append(f"file-count {len(actual)}")
    listed = sorted([f["path"] for f in outer["files"]])
    if sorted(set(listed) | {"subject-files.json"}) != actual:
        errors.append("outer-file-set-mismatch")
    for f in outer["files"]:
        p = SUBJ / f["path"]
        if p.is_symlink():
            errors.append("symlink " + f["path"])
        raw = p.read_bytes()
        if hashlib.sha256(raw).hexdigest() != f["sha256"] or len(raw) != f["bytes"]:
            errors.append("outer-pin " + f["path"])
    inner = json.loads((SUBJ / "subject-files.json").read_bytes())
    inner_rows = {f["path"]: f for f in inner["files"]}
    outer_rows = {f["path"]: f for f in outer["files"]}
    if set(inner_rows) != set(outer_rows) - {"subject-files.json"}:
        errors.append("inner-set-mismatch")
    for k, f in inner_rows.items():
        if outer_rows.get(k, {}).get("sha256") != f["sha256"] or outer_rows[k]["bytes"] != f["bytes"]:
            errors.append("inner-vs-outer " + k)
    pins = json.loads((SUBJ / "source-pins.json").read_bytes())
    if len(pins["files"]) != 47:
        errors.append(f"pin-count {len(pins['files'])}")
    if pins["directoryListings"]:
        errors.append("listings-nonempty")
    pin_results = []
    for f in pins["files"]:
        p = Path(f["path"])
        ok = p.is_file() and not p.is_symlink() and os.path.realpath(p) in (str(p), str(p).replace("/tmp/", "/private/tmp/", 1))
        raw = p.read_bytes() if p.is_file() else b""
        good = ok and hashlib.sha256(raw).hexdigest() == f["sha256"] and len(raw) == f["bytes"]
        pin_results.append({"path": f["path"], "ok": good})
        if not good:
            errors.append("external-pin " + f["path"])
    pycache = [d for d in dirs if "__pycache__" in d]
    if pycache:
        errors.append("pycache-in-subject")
    res = {"label": label, "outerSha256": hashlib.sha256(outer_raw).hexdigest(), "subjectFiles": actual,
           "subjectDirs": dirs, "externalPins": len(pin_results), "externalPinsOk": sum(r["ok"] for r in pin_results),
           "errors": errors}
    Path(out).write_text(json.dumps(res, indent=1) + "\n")
    print(label, "errors:", errors, "files:", len(actual), "pins ok:", res["externalPinsOk"], "/", len(pin_results))


if __name__ == "__main__":
    main()

