parent = ref.parse((S05 / "report-projection.schema.json").read_bytes())
patched = apply_patch(parent, patch["ops"])
add(patched)


def schema(selector, value):
    try:
        ref.validate({"$ref": selector}, value, registry)
        return "accept"
    except (ValidationError, ref.AdmissionError) as exc:
        return "SCHEMA " + str(exc).splitlines()[0][:200]


def host(fn):
    try:
        fn()
        return "accept"
    except M.Refusal as exc:
        return exc.code


