    data = B.assemble(desc, M)
    checks = {"membership": schema(N + "UnitMembershipV1", data["membership"]), "enumerationPlan": schema("opensip.product.enumeration-plan.1", data["enumerationPlan"]),
              "inventories": sorted({schema("opensip.product.subject-inventory.1", inv) for inv in data["subjectInventories"]}),
              "ownership": sorted({schema(N + "SourceUnitOwnershipV1", r) for r in data["sourceUnitOwnership"].values()})}
    if data["recognition"]["record"] is not None:
        checks["recognitionParameter"] = schema("opensip.product.framework-recognition-plan.1", data["recognition"]["record"])
    w = M.World(data)
    if data["recognition"]["record"] is not None:
        M.admit_recognition_plan(w, data["recognition"]["record"])
    return w, checks


def ctx(w, resolution):
    return {"projectId": w.project_id, "runId": w.run_id, "resolution": resolution, "graphResolution": resolution, "bounds": M.PUBLIC_BOUNDS}


def evidence_panel(w, resolution):
    panel = M.derive_symbol_evidence(w, resolution, BIG)
    return panel, schema(RID + "#/$defs/SymbolEvidencePanelV1", panel), host(lambda: M.admit_symbol_evidence(panel, ctx(w, resolution)))


