                                           "unit0": next(u for u in panel["entryRecognition"]["units"] if u["unitOrdinal"] == 0)["entryPoints"],
                                           "unit0Kind": w.units[0]["unitKind"], "unit0Members": w.units[0]["memberPackageRoots"]}
except Exception:
    out["C3-cargo-member-binary-entry"] = {"probeError": traceback.format_exc()}

# ---------------------------------------------------------------- C4 patch composition with another obligation's exact before/after remove-rows
try:
    other_ops = []
    for op in patch["ops"]:
        if op["op"] != "remove-rows":
            continue
        node, key = pointer_parent(parent, op["path"])
        rows_ = node[key]
        kept = [r for r in rows_ if (r[op["matchKey"]] if "matchKey" in op else r) not in ["step-duration"]]
        if len(kept) < len(rows_):
            other_ops.append(dict({k: v for k, v in op.items() if k not in ("before", "after", "match")}, match=["step-duration"], before=copy.deepcopy(rows_), after=kept))
    res = {"otherObligationOps": len(other_ops), "otherPaths": [o["path"] for o in other_ops]}
    for label, first, second in (("this-then-RP-DO-11", patch["ops"], other_ops), ("RP-DO-11-then-this", other_ops, patch["ops"])):
        try:
            apply_patch(apply_patch(parent, first), second)
            res[label] = "applied"
        except AssertionError as exc:
            res[label] = "REFUSED " + str(exc)
    res["setSemanticsCommute"] = True  # what check.py line 388 proves, ignoring before/after
    out["C4-patch-composition"] = res
except Exception:
    out["C4-patch-composition"] = {"probeError": traceback.format_exc()}

# ---------------------------------------------------------------- C5 featureMapSuccessor refs resolve? and the check.py predicate
try:
    reg = json.loads((SUBJ / "owner/evidence-design-successor.v1.json").read_bytes())

    def resolves(doc, pointer):
        node = doc
        for t in [unescape(t) for t in pointer.strip("/").split("/")]:
            if isinstance(node, dict) and t in node:
                node = node[t]
            else:
                return False
        return True
    refs = {r["ref"]: resolves(patched, r["ref"]) for rows_ in reg["featureMapSuccessor"].values() for r in rows_}
    bogus = "/$defs/GraphPanelV1/properties/reviewerBogusMember"
    out["C5-featureMap-refs"] = {"refsResolve": refs, "checkPredicateOnBogusRef": pointer_parent(patched, bogus)[0] is not None, "bogusResolves": resolves(patched, bogus)}
except Exception:
