try:
    d = B.mixed_desc()
    w0, _ = build_world(copy.deepcopy(d))
    c0 = M.derive_coupling(w0, test_origin_state=M.test_origin_state_fn(w0))
    d["facts"].append(B.fact("rev-i18-same-file-other-program", "imports", "resolved-target", "imports", B.ep(B.US, "symbol", "ts:shared/format"), B.ep(B.UW, "symbol", "ts:web/button")))
    w1, _ = build_world(d)
    c1 = M.derive_coupling(w1, test_origin_state=M.test_origin_state_fn(w1))

    def shared_web(c):
        keys = {o.get("packageName"): o["ownerKey"] for o in c["owners"]}
        cell = next(x for x in c["cells"] if x["fromOwnerKey"] == keys["@fx/shared"] and x["toOwnerKey"] == keys["@fx/web"])
        return {k: cell[k] for k in ("facts", "edges", "importerSymbols", "importerUniverses")}
    out["C6-cross-universe-duplicate"] = {"importerPaths": [w1.symbol_attribution(B.UW, "ts:web/shared-format")[0], w1.symbol_attribution(B.US, "ts:shared/format")[0]],
