try:
    t0 = time.time()
    n = 120
    files, units, membership, programs, packages, facts = [], [], {}, [], [], []
    for i in range(n):
        root = "packages/p%03d" % i
        files += [root + "/package.json", root + "/src/index.ts"]
        units.append({"root": root, "family": "tsjs", "mode": "js-synthesized", "kind": "js-program", "marker": root + "/package.json"})
        membership[root + "/src/index.ts"] = i
        programs.append({"root": root, "mode": "js-synthesized", "universe": B.H("rev-u%d" % i), "symbols": [{"id": "ts:p%03d/index" % i, "path": root + "/src/index.ts"}]})
        packages.append((root + "/package.json", "@rev/p%03d" % i))
    for i in range(n):
        for j in range(n):
            if i != j:
                facts.append(B.fact("rev-%d-%d" % (i, j), "imports", "resolved-target", "imports", B.ep(B.H("rev-u%d" % i), "symbol", "ts:p%03d/index" % i),
                                    B.ep(B.H("rev-u%d" % j), "symbol", "ts:p%03d/index" % j)))
    d = {"files": files, "units": units, "membership": membership, "programs": programs, "packages": packages, "recognition": {"explicit": []},
