    out["C7-coupling-size"] = {"packages": n, "facts": len(facts), "cells": len(c["cells"]), "owners": len(c["owners"]), "panelCanonicalBytes": total, "parts": parts,
                               "explorationCap": BIG, "exceedsCap": total > BIG, "drilldownProjection": c["drilldownProjection"], "absence": c["absence"],
