try:
    bp = base["budgetProfile"]
    metrics_schema = patched["$defs"]["SymbolEvidencePanelV1"]["properties"]["metrics"]
    out["C8-budget"] = {"budgetProfile": {k: bp[k] for k in ("documentMaxBytes", "explorationMaxCanonicalBytes", "maxPlannedSubjects", "projectionPriority", "maxSubjectIndexRows")},
