try:
    d = B.mixed_desc()
    d["recognition"]["explicit"] = ["src/main.rs"]
    w, _ = build_world(d)
    resolution = B.mixed_resolution(M)
    panel = M.derive_symbol_evidence(w, resolution, BIG)
